          if (!aabb_overlap(aa, bb)) continue;
          const dx = Math.min((aa.x + aa.w) - bb.x, (bb.x + bb.w) - aa.x);
          const dy = Math.min((aa.y + aa.h) - bb.y, (bb.y + bb.h) - aa.y);
